import { ENV_OBJ, warn } from './utils'

// 特别指定的不进行Promise封装的方法
const blackList = [
  'drawCanvas',
  'canIUse',
  'getPerformance',
  'reportAnalytics',
  'getMenuButtonBoundingClientRect',
  'reportMonitor',
  'reportEvent',
  'base64ToArrayBuffer',
  'arrayBufferToBase64',
  'getDeviceInfo',
  'getWindowInfo',
  'getAppBaseInfo',
  'getAppAuthorizeSetting',
  'getSystemSetting',
  'getApiCategory',
  'postMessageToReferrerPage',
  'postMessageToReferrerMiniProgram',
  'reportPerformance',
  'router',
  'nextTick',
  'checkIsPictureInPictureActive',
  'worklet',
  'revokeBufferURL',
  'getExptInfoSync',
  'getNFCAdapter',
  'isVKSupport'
]

function getMapFromList (list) {
  if (list && list.length) {
    const map = {}
    list.forEach((item) => {
      map[item] = true
    })
    return map
  }
}

function promisify (listObj, whiteList, customBlackList) {
  const result = {}
  const whiteListMap = getMapFromList(whiteList)
  const blackListMap = getMapFromList(blackList.concat(customBlackList))

  function promisifyFilter (key) {
    if (whiteListMap && whiteListMap[key] !== undefined) {
      return !!whiteListMap[key]
    } else {
      return !(blackListMap[key] || // 特别指定的方法
        /^get\w*Manager$/.test(key) || // 获取manager的api
        /^create(?!BLEConnection|BLEPeripheralServer)\w*$/.test(key) || // 创建上下文相关api
        /^(on|off)/.test(key) || // 以 on* 或 off开头的方法
        /\w+Sync$/.test(key) // 以Sync结尾的方法
      )
    }
  }

  Object.keys(listObj).forEach(key => {
    if (typeof listObj[key] !== 'function') {
      return
    }
    if (!promisifyFilter(key)) {
      result[key] = listObj[key].bind(ENV_OBJ)
    } else {
      result[key] = function (...args) {
        const obj = args[0] || {}
        if (obj.usePromise === false) {
          return listObj[key].apply(ENV_OBJ, args)
        }
        if (!args[0]) args.unshift(obj)
        let returned
        const promise = new Promise((resolve, reject) => {
          const originSuccess = obj.success
          const originFail = obj.fail
          if (originSuccess || originFail) {
            warn(`The [${key}] method has been promisified, please use .then or .catch to handle the result, if you need to handle the result with options.success/fail, please set options.usePromise to false to close the promisify in this call temporarily. `)
          }
          obj.success = function (res) {
            originSuccess && originSuccess.call(this, res)
            resolve(res)
          }
          obj.fail = function (e) {
            originFail && originFail.call(this, e)
            reject(e)
          }
          returned = listObj[key].apply(ENV_OBJ, args)
        })
        promise.__returned = returned
        return promise
      }
    }
  })

  return result
}

export default promisify
import axios from 'axios'
import { successHandle, failHandle, defineUnsupportedProps } from '../../../common/js'
import RequestTask from './RequestTask'
import { serialize, buildUrl } from '@mpxjs/utils'

function request (options = { url: '' }) {
  const CancelToken = axios.CancelToken
  const source = CancelToken.source()
  const requestTask = new RequestTask(source.cancel)

  let {
    url,
    data = {},
    method = 'GET',
    dataType = 'json',
    responseType = 'text',
    timeout = global.__networkTimeout || 60 * 1000,
    header = {},
    success = null,
    fail = null,
    complete = null
  } = options
  method = method.toUpperCase()
  if (method === 'GET') {
    url = buildUrl(url, data)
    data = {}
  }

  if (
    method === 'POST' &&
    typeof data !== 'string' && // string 不做处理
    (header['Content-Type'] === 'application/x-www-form-urlencoded' ||
      header['content-type'] === 'application/x-www-form-urlencoded')
  ) {
    data = serialize(data)
  }

  /**
   * axios 的其他参数
   * baseURL
   * transformRequest
   * transformResponse,
   * headers,
   * params,
   * paramsSerializer,
   * withCredentials,
   * adapter,
   * auth,
   * xsrfCookieName,
   * xsrfHeaderName,
   * onUploadProgress,
   * onDownloadProgress,
   * maxContentLength,
   * maxBodyLength,
   * validateStatus,
   * maxRedirects,
   * socketPath,
   * httpAgent,
   * httpsAgent,
   * decompress
   */
  const rOptions = Object.assign(options, {
    method,
    url,
    data,
    headers: header,
    responseType,
    timeout,
    cancelToken: source.token,
    transitional: {
      // silent JSON parsing mode
      // `true`  - ignore JSON parsing errors and set response.data to null if parsing failed (old behaviour)
      // `false` - throw SyntaxError if JSON parsing failed (Note: responseType must be set to 'json')
      silentJSONParsing: true, // default value for the current Axios version
      // try to parse the response string as JSON even if `responseType` is not 'json'
      forcedJSONParsing: false,
      // throw ETIMEDOUT error instead of generic ECONNABORTED on request timeouts
      clarifyTimeoutError: false
    }
  })
  if (method === 'GET') {
    rOptions.params = rOptions.data || {}
    delete rOptions.data
  }
  axios(rOptions).then(res => {
    let data = res.data
    if (dataType === 'json' && typeof data === 'string') {
      try {
        data = JSON.parse(data)
      } catch (e) {
      }
    }

    const result = Object.assign({}, res, {
      errMsg: 'request:ok',
      data,
      statusCode: res.status,
      header: res.headers
    })
    defineUnsupportedProps(result, ['cookies', 'profile', 'exception'])
    successHandle(result, success, complete)
    return result
  }).catch(err => {
    const realError = err || {}
    const response = realError.response || {}
    const res = {
      errMsg: `request:fail ${err}`,
      statusCode: response.status,
      header: response.headers,
      data: response.data
    }
    Object.assign(res, realError)
    failHandle(res, fail, complete)
  })

  return requestTask
}

export {
  request
}
class RequestTask {
  constructor (abortCb) {
    this._abortCb = abortCb
  }

  abort () {
    if (typeof this._abortCb === 'function') {
      this._abortCb()
    }
  }
}

export default RequestTask
import { successHandle, failHandle, isTabBarPage, throwSSRWarning, isBrowser, resolvePath } from '../../../common/js'
import { EventChannel } from '../event-channel'

let routeCount = 0

function redirectTo (options = {}) {
  if (!isBrowser) {
    throwSSRWarning('redirectTo API is running in non browser environments')
    return
  }
  const router = global.__mpxRouter
  if (router) {
    if (isTabBarPage(options.url, router)) {
      const res = { errMsg: 'redirectTo:fail can not redirectTo a tabBar page' }
      failHandle(res, options.fail, options.complete)
    }
    router.__mpxAction = { type: 'redirect' }
    if (routeCount === 0 && router.currentRoute.query.routeCount) routeCount = router.currentRoute.query.routeCount
    router.replace(
      {
        path: options.url,
        query: {
          routeCount: ++routeCount
        }
      },
      () => {
        const res = { errMsg: 'redirectTo:ok' }
        successHandle(res, options.success, options.complete)
      },
      err => {
        const res = { errMsg: `redirectTo:fail ${err}` }
        failHandle(res, options.fail, options.complete)
      }
    )
  }
}

function navigateTo (options = {}) {
  if (!isBrowser) {
    throwSSRWarning('navigateTo API is running in non browser environments')
    return
  }
  const router = global.__mpxRouter
  if (router) {
    if (isTabBarPage(options.url, router)) {
      const res = { errMsg: 'navigateTo:fail can not navigateTo a tabBar page' }
      failHandle(res, options.fail, options.complete)
    }
    const finalPath = resolvePath(options.url, router.currentRoute.path).slice(1)
    const eventChannel = new EventChannel()
    router.__mpxAction = {
      type: 'to'
    }
    global.__mpxEventChannel = {
      route: finalPath,
      eventChannel
    }
    if (options.events) {
      eventChannel._addListeners(options.events)
    }
    if (routeCount === 0 && router.currentRoute.query.routeCount) routeCount = router.currentRoute.query.routeCount
    router.push(
      {
        path: options.url,
        query: {
          routeCount: ++routeCount
        }
      },
      () => {
        const res = { errMsg: 'navigateTo:ok', eventChannel }
        successHandle(res, options.success, options.complete)
      },
      err => {
        const res = { errMsg: `navigateTo:fail ${err}` }
        failHandle(res, options.fail, options.complete)
      }
    )
  }
}

function navigateBack (options = {}) {
  if (!isBrowser) {
    throwSSRWarning('navigateBack API is running in non browser environments')
    return
  }
  const router = global.__mpxRouter
  if (router) {
    let delta = options.delta || 1
    const stackLength = router.stack.length
    if (stackLength > 1 && delta >= stackLength) {
      delta = stackLength - 1
    }
    router.__mpxAction = {
      type: 'back',
      delta
    }
    router.go(-delta)
    const res = { errMsg: 'navigateBack:ok' }
    successHandle(res, options.success, options.complete)
  }

